//! Groth16 proof fixtures generated by `solana/scripts/gen-zk-fixtures.mjs` for the report
//! circuit (SPEC §8). Each fixture carries the public inputs and the 256-byte on-chain proof.

use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
pub struct FixtureFile {
    pub terms: Terms,
    pub fixtures: Vec<Fixture>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Terms {
    pub theta: String,
    pub r_wad: String,
    pub terms_commitment: String,
    pub zero_income_commitment: String,
    pub units: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Fixture {
    pub name: String,
    pub public: PublicInputs,
    pub proof: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct PublicInputs {
    pub terms_commitment: String,
    pub units_outstanding: String,
    pub fx_avg_wad: String,
    pub prior_income_commitment: String,
    pub income_commitment: String,
    pub payment_usd: String,
}

pub fn hex32(s: &str) -> [u8; 32] {
    let bytes = hex::decode(s.trim_start_matches("0x")).expect("hex");
    let mut out = [0u8; 32];
    out.copy_from_slice(&bytes);
    out
}

pub fn dec_u64(s: &str) -> u64 {
    s.parse().expect("u64")
}

impl Fixture {
    pub fn proof_bytes(&self) -> Vec<u8> {
        hex::decode(self.proof.trim_start_matches("0x")).expect("proof hex")
    }
    pub fn terms_commitment(&self) -> [u8; 32] {
        hex32(&self.public.terms_commitment)
    }
    pub fn income_commitment(&self) -> [u8; 32] {
        hex32(&self.public.income_commitment)
    }
    pub fn units(&self) -> u64 {
        dec_u64(&self.public.units_outstanding)
    }
    pub fn fx_avg_wad(&self) -> u64 {
        dec_u64(&self.public.fx_avg_wad)
    }
    pub fn payment_usd(&self) -> u64 {
        dec_u64(&self.public.payment_usd)
    }
}

/// Loads `tests/fixtures/zk/report_fixtures.json`.
pub fn load() -> FixtureFile {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/zk/report_fixtures.json");
    let text = std::fs::read_to_string(path).expect("fixtures present; run solana/scripts/gen-zk-fixtures.mjs");
    serde_json::from_str(&text).expect("fixture json")
}

impl FixtureFile {
    pub fn get(&self, name: &str) -> &Fixture {
        self.fixtures.iter().find(|f| f.name == name).unwrap_or_else(|| panic!("fixture {name}"))
    }
    pub fn terms_commitment(&self) -> [u8; 32] {
        hex32(&self.terms.terms_commitment)
    }
}
